use std::time::{SystemTime,UNIX_EPOCH};
use serde_json::{json,Map,Value};use uuid::Uuid;use crate::typed_blob_store::BlobCodec;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum AgentMode{Default,Plan,Debug,Search}
impl AgentMode{pub fn as_str(self)->&'static str{match self{Self::Default=>"default",Self::Plan=>"plan",Self::Debug=>"debug",Self::Search=>"search"}}fn parse(s:&str)->Option<Self>{match s{"default"=>Some(Self::Default),"plan"=>Some(Self::Plan),"debug"=>Some(Self::Debug),"search"=>Some(Self::Search),_=>None}}}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum ApprovalModeSetting{Allowlist,Unrestricted,AutoReview}
impl ApprovalModeSetting{pub fn as_str(self)->&'static str{match self{Self::Allowlist=>"allowlist",Self::Unrestricted=>"unrestricted",Self::AutoReview=>"auto-review"}}fn parse(s:&str)->Option<Self>{match s{"allowlist"=>Some(Self::Allowlist),"unrestricted"=>Some(Self::Unrestricted),"auto-review"=>Some(Self::AutoReview),_=>None}}}
#[derive(Clone,Debug,PartialEq,Eq)]pub struct AgentSubagentInfo{pub parent_agent_id:String,pub root_parent_agent_id:String,pub tool_call_id:String,pub type_name:String}
#[derive(Clone,Debug,PartialEq)]pub struct AgentMetadata{pub agent_id:String,pub latest_root_blob_id:Vec<u8>,pub name:String,pub mode:AgentMode,pub is_run_everything:bool,pub approval_mode:Option<ApprovalModeSetting>,pub created_at:f64,pub last_used_model:Option<String>,pub last_debug_server_port:Option<u64>,pub current_plan_uri:Option<String>,pub subagent_info:Option<AgentSubagentInfo>,pub blob_encryption_key:Option<String>}
impl AgentMetadata{pub fn default_for(id:impl Into<String>)->Self{Self{agent_id:id.into(),latest_root_blob_id:vec![],name:"New Agent".into(),mode:AgentMode::Default,is_run_everything:false,approval_mode:None,created_at:now_ms()as f64,last_used_model:None,last_debug_server_port:None,current_plan_uri:None,subagent_info:None,blob_encryption_key:Some(generate_key())}}}
#[derive(Clone,Copy,Debug,Default)]pub struct AgentMetadataSerde;
impl AgentMetadataSerde{
 pub fn serialize(&self,v:&AgentMetadata)->Result<Vec<u8>,String>{let mut o=Map::new();o.insert("agentId".into(),json!(v.agent_id));o.insert("latestRootBlobId".into(),json!(hex(&v.latest_root_blob_id)));o.insert("name".into(),json!(v.name));o.insert("mode".into(),json!(v.mode.as_str()));o.insert("isRunEverything".into(),json!(v.is_run_everything));o.insert("createdAt".into(),json!(v.created_at));if let Some(x)=v.approval_mode{o.insert("approvalMode".into(),json!(x.as_str()));}if let Some(x)=&v.last_used_model{o.insert("lastUsedModel".into(),json!(x));}if let Some(x)=v.last_debug_server_port.filter(|x|*x>0){o.insert("lastDebugServerPort".into(),json!(x));}if let Some(x)=&v.current_plan_uri{o.insert("currentPlanUri".into(),json!(x));}if let Some(x)=&v.subagent_info{if valid_subagent(x){o.insert("subagentInfo".into(),json!({"parentAgentId":x.parent_agent_id,"rootParentAgentId":x.root_parent_agent_id,"toolCallId":x.tool_call_id,"typeName":x.type_name}));}}if let Some(x)=v.blob_encryption_key.as_deref().filter(|x|valid_key(x)){o.insert("blobEncryptionKey".into(),json!(x));}serde_json::to_vec(&Value::Object(o)).map_err(|e|e.to_string())}
 pub fn deserialize(&self,b:&[u8])->Result<AgentMetadata,String>{let v:Value=serde_json::from_slice(b).map_err(|e|e.to_string())?;let o=v.as_object().ok_or("Agent metadata must be an object")?;let id=o.get("agentId").and_then(Value::as_str).map(str::to_owned).unwrap_or_else(||Uuid::new_v4().to_string());let mut m=AgentMetadata::default_for(id);if let Some(x)=o.get("latestRootBlobId"){if let Some(s)=x.as_str(){m.latest_root_blob_id=unhex(s)?}}if let Some(x)=o.get("name"){m.name=x.as_str().ok_or("name must be string")?.into()}if let Some(x)=o.get("createdAt"){m.created_at=x.as_f64().ok_or("createdAt must be number")?}let mode=o.get("mode").and_then(Value::as_str).unwrap_or("default");if mode=="auto-run"{m.mode=AgentMode::Default;m.is_run_everything=true}else{m.mode=AgentMode::parse(mode).unwrap_or(AgentMode::Default);m.is_run_everything=o.get("isRunEverything")==Some(&Value::Bool(true))}m.approval_mode=o.get("approvalMode").and_then(Value::as_str).and_then(ApprovalModeSetting::parse);m.last_used_model=opt_string(o,"lastUsedModel")?;m.current_plan_uri=opt_string(o,"currentPlanUri")?;m.last_debug_server_port=match o.get("lastDebugServerPort"){None=>None,Some(x)=>Some(x.as_u64().filter(|n|*n>0).ok_or("lastDebugServerPort must be positive integer")?)};m.subagent_info=parse_subagent(o.get("subagentInfo"));m.blob_encryption_key=Some(o.get("blobEncryptionKey").and_then(Value::as_str).filter(|x|valid_key(x)).map(str::to_owned).unwrap_or_else(generate_key));Ok(m)}
 pub fn normalize_field(key:&str,v:Value,fallback:&str)->Result<Value,String>{Ok(match key{"agentId"=>Value::String(v.as_str().unwrap_or(fallback).into()),"latestRootBlobId"=>Value::String(hex(&unhex(v.as_str().ok_or("latestRootBlobId must be hex")?)?)),"name"=>Value::String(v.as_str().ok_or("name must be string")?.into()),"mode"=>{let s=v.as_str().ok_or("mode must be string")?;Value::String(if s=="auto-run"||AgentMode::parse(s).is_none(){"default"}else{s}.into())},"isRunEverything"=>Value::Bool(v==Value::Bool(true)),"approvalMode"=>v.as_str().and_then(ApprovalModeSetting::parse).map(|x|Value::String(x.as_str().into())).unwrap_or(Value::Null),"createdAt"=>if v.as_f64().is_some(){v}else{return Err("createdAt must be numeric".into())},"lastUsedModel"|"currentPlanUri"=>v.as_str().map(|s|Value::String(s.into())).unwrap_or(Value::Null),"lastDebugServerPort"=>v.as_u64().filter(|n|*n>0).map(|n|Value::Number(n.into())).unwrap_or(Value::Null),"subagentInfo"=>parse_subagent(Some(&v)).filter(valid_subagent).map(|x|json!({"parentAgentId":x.parent_agent_id,"rootParentAgentId":x.root_parent_agent_id,"toolCallId":x.tool_call_id,"typeName":x.type_name})).unwrap_or(Value::Null),"blobEncryptionKey"=>Value::String(v.as_str().filter(|x|valid_key(x)).map(str::to_owned).unwrap_or_else(generate_key)),_=>v})}
}
impl BlobCodec<AgentMetadata> for AgentMetadataSerde{fn encode(&self,v:&AgentMetadata)->Result<Vec<u8>,String>{self.serialize(v)}fn decode(&self,b:&[u8])->Result<AgentMetadata,String>{self.deserialize(b)}fn blob_type(&self)->Option<&'static str>{Some("json")}}
fn valid_subagent(x:&AgentSubagentInfo)->bool{!x.parent_agent_id.is_empty()&&!x.root_parent_agent_id.is_empty()&&!x.tool_call_id.is_empty()&&!x.type_name.is_empty()}
fn parse_subagent(v:Option<&Value>)->Option<AgentSubagentInfo>{let o=v?.as_object()?;Some(AgentSubagentInfo{parent_agent_id:o.get("parentAgentId")?.as_str()?.to_owned(),root_parent_agent_id:o.get("rootParentAgentId")?.as_str()?.to_owned(),tool_call_id:o.get("toolCallId")?.as_str()?.to_owned(),type_name:o.get("typeName")?.as_str()?.to_owned()})}
fn opt_string(o:&Map<String,Value>,k:&str)->Result<Option<String>,String>{match o.get(k){None=>Ok(None),Some(Value::String(s))=>Ok(Some(s.clone())),Some(_)=>Err(format!("{k} must be a string"))}}
fn valid_key(s:&str)->bool{s.len()==64&&s.bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b))}
fn generate_key()->String{let mut b=[0u8;32];b[..16].copy_from_slice(Uuid::new_v4().as_bytes());b[16..].copy_from_slice(Uuid::new_v4().as_bytes());hex(&b)}
fn now_ms()->u64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_millis().min(u64::MAX as u128)as u64}
fn hex(b:&[u8])->String{const H:&[u8;16]=b"0123456789abcdef";let mut s=String::new();for x in b{s.push(H[(x>>4)as usize]as char);s.push(H[(x&15)as usize]as char)}s}
fn unhex(s:&str)->Result<Vec<u8>,String>{if s.len()%2!=0||!s.bytes().all(|b|b.is_ascii_hexdigit()){return Err("hex must have even length and contain only hex digits".into())}let mut out=Vec::new();for p in s.as_bytes().chunks_exact(2){out.push((((p[0]as char).to_digit(16).ok_or("hex")?)<<4|((p[1]as char).to_digit(16).ok_or("hex")?))as u8)}Ok(out)}
#[cfg(test)]mod tests{use super::*;#[test]fn metadata_normalizes_legacy_values(){let s=AgentMetadataSerde;let m=s.deserialize(br#"{"agentId":"a","latestRootBlobId":"0102","mode":"auto-run","isRunEverything":false,"createdAt":123,"blobEncryptionKey":"bad"}"#).unwrap();assert_eq!(m.mode,AgentMode::Default);assert!(m.is_run_everything);assert_eq!(m.latest_root_blob_id,vec![1,2]);assert!(m.blob_encryption_key.as_deref().is_some_and(valid_key));assert!(s.deserialize(br#"{"latestRootBlobId":"zz"}"#).is_err())}}
